content.title:
grep -n "\\\(\|\\\\\[" "F2/Unidad VI.md" "F2/Formulario Unidad VI.md" "F2/Unidad VII.md" "F2/Formulario Unidad VII.md" | head; echo "---tables without blank line check---"; python - <<'PY'
import re, pathlib
for p in ["F2/Unidad VI.md","F2/Formulario Unidad VI.md","F2/Unidad VII.md","F2/Formulario Unidad VII.md"]:
    lines=pathlib.Path(p).read_text(encoding="utf-8").splitlines()
    for i,l in enumerate(lines):
        if l.strip().startswith("|") and i>0 and lines[i-1].strip() and not lines[i-1].strip().startswith("|"):
            print(p, i+1, repr(lines[i-1][:60]))
PY

